function tradeRowsHTMLD5(w,buyer,seller){return RES().map(k=>{const a=assessTradeD5(w,buyer,seller,k,false),q=a.quote,last=[...(w.recentTrades||[])].reverse().find(r=>Number(r.buyerId)===Number(buyer.id)&&Number(r.sellerId)===Number(seller.id)&&r.resource===k),lastUnit=last?Number(last.unitPrice??(Number(last.price||0)/Math.max(.001,Number(last.qty||0)))):null;return`<div class="v32d5-quote-row"><div class="v32d5-rname">${esc(icon(k))} <b>${esc(label(k))}</b></div><div><span>최대 매수가</span><b>${q?Number(q.wtp).toFixed(3):'—'}G</b></div><div><span>판매호가</span><b>${q?Number(q.ask).toFixed(3):'—'}G</b></div><div><span>도착가</span><b>${q?Number(q.landed).toFixed(3):'—'}G</b></div><div class="v32d5-status">${esc(STATUS[a.reason]||a.reason)}</div><details><summary>가격 구성</summary><div class="small muted">국내 판매기준 ${q?Number(q.sellLocal).toFixed(3):'—'}G · 반복수요 +${q?(Number(q.repeatPrem||0)*100).toFixed(1):'0'}% · 전략경계 +${q?(Number(q.strategyPrem||0)*100).toFixed(1):'0'}% · 관계 ${(q&&Number(q.relationAdj||0)>=0)?'+':''}${q?(Number(q.relationAdj||0)*100).toFixed(1):'0'}% · 현금압박 -${q?(Number(q.cashDiscount||0)*100).toFixed(1):'0'}% · 운송 ${q?Number(q.transport).toFixed(3):'—'}G${lastUnit!=null?` · 최근 체결 ${lastUnit.toFixed(3)}G`:''}</div></details></div>`;}).join('');}
function partnerBoardD5(ui,v){const w=ui.world,others=(w.activeVillages||[]).filter(x=>x.id!==v.id);if(!others.length)return'';let pid=Number(ui.v32d5TradePartnerId);if(!others.some(x=>x.id===pid))pid=others[0].id;ui.v32d5TradePartnerId=pid;const o=others.find(x=>x.id===pid),bal=tradeBalanceD5(v,w),f=recentFunnelD5(v,w),frows=Object.entries(f).sort((a,b)=>b[1]-a[1]).slice(0,7),st=ensureD5(v);return`<div class="v32d5-board"><div class="section-head"><div><strong>🌐 D5 국제시장 호가판</strong><div class="small muted">실제 AI 거래 계산과 동일한 현재 호가 · Market Gold 결제</div></div><label class="small">상대국 <select id="v32d5Partner">${others.map(x=>`<option value="${x.id}"${x.id===pid?' selected':''}>${esc(x.name)}</option>`).join('')}</select></label></div><div class="v32d5-summary"><span>최근 1년 무역수지 <b>${bal.balance>=0?'+':''}${bal.balance.toFixed(1)}G</b></span><span>시장 Gold <b>${marketGoldNation(v,w).toFixed(1)}G</b></span><span>자립 압력 <b>${Number(st.selfReliancePressure||0).toFixed(2)}</b></span><span>국고지원(금년) <b>${Number(st.supportSpentYear||0).toFixed(1)}G</b></span></div><details open><summary><b>${esc(o.name)} → ${esc(v.name)}</b> · ${esc(v.name)}의 수입 조건</summary><div class="v32d5-quote-grid">${tradeRowsHTMLD5(w,v,o)}</div></details><details><summary><b>${esc(v.name)} → ${esc(o.name)}</b> · ${esc(v.name)}의 수출 조건</summary><div class="v32d5-quote-grid">${tradeRowsHTMLD5(w,o,v)}</div></details><div class="v32d5-funnel"><b>최근 1년 Trade Funnel</b> ${frows.length?frows.map(([k,n])=>`<span>${esc(k)} ${n}</span>`).join(''):'<span>관측 없음</span>'}</div></div>`;}
function rewriteRecentTradesD5(root,v){const lists=[...root.querySelectorAll('.trade-list')],list=lists.find(x=>!x.classList.contains('v17-market-knowledge'));if(!list)return;const rows=[...(v.tradeHistory||[])].reverse();list.innerHTML=rows.map(r=>{const def=NS.RESOURCE_DEFS?.[r.resource]||{},unit=Number(r.unitPrice??(Number(r.price||0)/Math.max(.001,Number(r.qty||0)))),land=Number(r.landedUnitPrice??unit);return`<div class="trade-row"><strong>${esc(r.time||'')}</strong><br>${esc(r.seller)} → ${esc(r.buyer)} · ${esc(def.icon||'')} ${esc(def.label||r.resource)} ${Number(r.qty||0).toFixed(2)}<div class="muted small">경로 ${Number(r.routeCost||0).toFixed(2)} · 판매 ${unit.toFixed(3)}G · 도착 ${land.toFixed(3)}G · 총 ${Number(r.grossCost??r.price??0).toFixed(2)}G${r.supportReason?` · 국고지원 ${esc(r.supportReason)}`:''}</div></div>`;}).join('')||'<div class="muted">아직 교역 기록이 없습니다.</div>';}
