if(Array.isArray(NS.PATCH_NOTES)&&!NS.PATCH_NOTES.some(x=>x.version==='V0.32D5'))NS.PATCH_NOTES.unshift({version:'V0.32D5',date:'2026-09-26',title:'후기 도시·물류·국제경제 안정화',summary:'D4 장기주행에서 드러난 벨른·노렌형 주거 프로젝트 교착, 키오형 식량 last-mile 실패, 산업 microtrade와 국제자본 편중을 정리하고 국가쌍별 실제 호가판을 추가합니다.',sections:[['주거 교착',['PROJECT_OR_LABOR를 PROJECT_CAP / NO_BUILDERS / LABOR_SHORTAGE / HOUSING_PROJECT_QUEUE / MATERIAL_PAYMENT 등으로 세분화합니다.','심각한 과밀에서는 일반 공사가 마지막 슬롯을 선점하지 못하도록 주거 우선 슬롯을 예약하고 D3의 실제 주거 해결 경로를 15일 간격으로 재시도합니다.']],['식량 last-mile',['기존 지역 물류를 우선 유지하고, 비축 6일 미만·Hunger 85+ 정착지가 남을 때만 국가 전체 잉여 Settlement를 탐색하는 비상 relay를 사용합니다.','실제 donor stock을 이동하며 passable route 비용과 capacity를 적용하고 실패 원인을 DONOR_RESERVE / NO_ROUTE / CAPACITY / NO_STOCK / STORAGE로 기록합니다.']],['국제경제 V2.1',['철광석/철/도구에 경제적 최소 거래량을 두어 0.2 단위 반복 microtrade를 억제합니다.','반복구매 프리미엄은 최근 3년 거래량·거래액·상대 의존도와 휴면기간을 사용하며 전략+반복 프리미엄 합산 상한을 둡니다.','수출국의 과잉 시장 Gold 일부는 실제 Person 지갑으로 보존형 배당되어 소비·세금 순환으로 되돌아갑니다.','Treasury 국제구매 지원은 생존 식량, 구조적 목재/석재, 고긴급 전략산업에만 허용하고 연간 예산을 둡니다.']],['관측·UI',['모든 교역 자원명은 RESOURCE_DEFS에서 읽어 철광석/철/도구가 undefined로 표시되지 않습니다.','D4 국제가격 박스의 겹침을 제거하고 국제시장 호가판을 정상 document flow에 배치합니다.','선택 국가↔상대국 양방향으로 모든 자원의 최대 매수가·판매호가·도착가·거래상태와 반복/전략/관계/현금압박/운송 구성요소를 표시합니다.','Trade Funnel은 최근 1년 rolling 30일 버킷과 NO_ROUTE_MARKET/RANGE/PATH 하위 원인을 표시합니다.']],['성능',['동일 일자 국가쌍·자원 호가 계산을 캐시하고, microtrade 억제 및 저빈도 주거/식량 fallback pulse로 후기 반복 계산과 로그를 줄입니다.']]]});
(function(){const KEY='village-observer-v0-32d5',fallback=['village-observer-v0-32d4','village-observer-v0-32d3','village-observer-v0-32d2','village-observer-v0-32d1','village-observer-v0-32d','village-observer-v0-32c2','village-observer-v0-32c1a','village-observer-v0-32c1','village-observer-v0-32b','village-observer-v0-32a','village-observer-v0-31i','village-observer-v0-31h','village-observer-v0-31g','village-observer-v0-31f'];function dl(name,text,type='application/json'){const blob=new Blob([text],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}NS.SaveSystem={save(w){localStorage.setItem(KEY,JSON.stringify(w.serialize()));},load(){let r=localStorage.getItem(KEY);for(const k of fallback)if(!r)r=localStorage.getItem(k);return r?NS.World.from(JSON.parse(r)):null;},export(w){dl(`village-observer-v032D5-save-${w.year}y.json`,JSON.stringify(w.serialize()));},exportDevJSON(w){dl(`village-observer-v032D5-devlog-${w.telemetry.sessionId}.json`,JSON.stringify(w.telemetry.toJSON(w)));},exportDevCSV(w){dl(`village-observer-v032D5-snapshots-${w.telemetry.sessionId}.csv`,'\ufeff'+w.telemetry.snapshotsCSV(),'text/csv;charset=utf-8');},async import(file){return NS.World.from(JSON.parse(await file.text()));},async importMap(file){return attachD5(NS.V019.worldFromMapData(JSON.parse(await file.text())));}};})();
